const loaders = {
  html: () => import("./renderers/html.js"),
  pdf:  () => import("./renderers/pdf.js"),
};

export async function lookup(name) {
  const load = loaders[name];
  if (!load) throw new Error(`unknown renderer: ${name}`);   // fail fast
  return (await load()).default;                              // specifier -> module
}
